#!/usr/bin/env python3
"""Emit scripts/sprite_db.gd from every assets/template/game/sprites/*/frames.json.

A literal GDScript table keeps frame pivots export-safe (no runtime JSON) and
lets Godot see every texture path for the all-resources Web export.
"""
import json
from pathlib import Path

root = Path("assets/template/game/sprites")
lines = [
    "extends RefCounted",
    "## Generated by tools/art/build_sprite_db.py — do not edit by hand.",
    "## FRAMES[sheet][frame] = [texture path, pivot (feet/centre, 2x source px)]",
    "const SOURCE_SCALE := 0.5",
    "const FRAMES := {",
]
for sheet in sorted(p for p in root.iterdir() if p.is_dir()):
    meta = json.loads((sheet / "frames.json").read_text())
    lines.append(f'\t"{sheet.name}": {{')
    for name, f in meta["frames"].items():
        px, py = f["pivot"]
        lines.append(f'\t\t"{name}": ["res://{sheet.as_posix()}/{f["file"]}", Vector2({px}, {py})],')
    lines.append("\t},")
lines.append("}")
Path("scripts/sprite_db.gd").write_text("\n".join(lines) + "\n")
print("wrote scripts/sprite_db.gd")
